package cn.breezeth.kaleidoscope_grilling.mixin;
import cn.breezeth.kaleidoscope_grilling.TypedOilPotAccess; import net.minecraft.nbt.CompoundTag; import org.spongepowered.asm.mixin.Mixin; import org.spongepowered.asm.mixin.Shadow; import org.spongepowered.asm.mixin.Unique; import org.spongepowered.asm.mixin.injection.At; import org.spongepowered.asm.mixin.injection.Inject; import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
@Mixin(targets="com.github.ysbbbbbb.kaleidoscopecookery.blockentity.decoration.OilPotBlockEntity",remap=false)
public abstract class OilPotBlockEntityMixin implements TypedOilPotAccess {@Unique private String grilling$oilType="";@Shadow public abstract int getOilCount();@Shadow public abstract void setOilCount(int count);@Override public String grilling$getOilType(){return grilling$oilType;}@Override public void grilling$setOilType(String type){grilling$oilType=type;}@Override public int grilling$getOilCount(){return getOilCount();}@Override public void grilling$setOilCount(int count){setOilCount(count);}@Inject(method="saveAdditional",at=@At("TAIL"))private void grilling$save(CompoundTag tag,CallbackInfo ci){tag.putString("GrillingOilType",grilling$oilType);}@Inject(method="load",at=@At("TAIL"))private void grilling$load(CompoundTag tag,CallbackInfo ci){grilling$oilType=tag.getString("GrillingOilType");}}
